<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['accion']??'')==='proveedor'){$nombre=trim($_POST['nombre']??'');$doc=trim($_POST['documento']??'');$tel=trim($_POST['telefono']??'');if($nombre==='')$err='Indica el nombre del proveedor.';else{$s=$mysqli->prepare('INSERT INTO proveedores(nombre,documento,telefono) VALUES(?,?,?)');$s->bind_param('sss',$nombre,$doc,$tel);$msg=$s->execute()?'Proveedor agregado.':'No se pudo guardar el proveedor.';$s->close();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['accion']??'')==='compra'){
 $prov=(int)($_POST['proveedor_id']??0);$pid=(int)($_POST['producto_id']??0);$num=trim($_POST['numero']??'');$lote=trim($_POST['lote']??'');$vence=$_POST['vencimiento']??'';$qty=filter_var($_POST['cantidad']??null,FILTER_VALIDATE_INT);$costo=filter_var($_POST['costo']??null,FILTER_VALIDATE_FLOAT);
 if(!$prov||!$pid||$num===''||$lote===''||!$vence||!$qty||$qty<1||$costo===false||$costo<0)$err='Completa proveedor, producto, factura, lote, vencimiento, cantidad y costo correctamente.';
 else try{$mysqli->begin_transaction();$total=round($qty*$costo,2);$userId=$_SESSION['farmacia_usuario_id']??null;$s=$mysqli->prepare('INSERT INTO compras(proveedor_id,numero,total,usuario_id) VALUES(?,?,?,?)');$s->bind_param('isdi',$prov,$num,$total,$userId);$s->execute();$compraId=$mysqli->insert_id;$s=$mysqli->prepare('INSERT INTO lotes_producto(producto_id,numero_lote,fecha_vencimiento,cantidad_inicial,cantidad_disponible) VALUES(?,?,?,?,?)');$s->bind_param('issii',$pid,$lote,$vence,$qty,$qty);$s->execute();$loteId=$mysqli->insert_id;$s=$mysqli->prepare('INSERT INTO detalle_compra(compra_id,producto_id,lote_id,cantidad,costo_unitario,subtotal) VALUES(?,?,?,?,?,?)');$s->bind_param('iiiidd',$compraId,$pid,$loteId,$qty,$costo,$total);$s->execute();$s=$mysqli->prepare('UPDATE productos SET stock=stock+? WHERE id=?');$s->bind_param('ii',$qty,$pid);$s->execute();$u=$_SESSION['farmacia_usuario_id']??null;$tipo='compra';$ref=$num;$s=$mysqli->prepare('INSERT INTO movimientos_inventario(producto_id,lote_id,tipo,cantidad,referencia,usuario_id) VALUES(?,?,?,?,?,?)');$s->bind_param('iisisi',$pid,$loteId,$tipo,$qty,$ref,$u);$s->execute();$mysqli->commit();$msg='Compra registrada y existencias actualizadas.';}catch(Throwable $e){$mysqli->rollback();$err='No se pudo registrar. Verifica que el número de compra no esté repetido y que las tablas estén actualizadas.';}
}
$ps=$mysqli->query('SELECT id,nombre FROM proveedores WHERE activo=1 ORDER BY nombre');$provs=[];if($ps)while($r=$ps->fetch_assoc())$provs[]=$r;$pr=$mysqli->query('SELECT id,nombre FROM productos WHERE activo=1 ORDER BY nombre');$prods=[];if($pr)while($r=$pr->fetch_assoc())$prods[]=$r;
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compras e inventario</title><style>body{font:15px Arial;background:#f2f7f5;color:#243b37;margin:0}.wrap{padding:22px}.box{background:#fff;padding:22px;border-radius:12px;margin-bottom:16px}h1,h2{color:#087f73}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}label{display:block;margin:8px 0 5px;font-weight:bold}input,select,button{width:100%;padding:10px;border:1px solid #ccd;border-radius:7px;font:inherit}button,.btn{background:#087f73;color:white;border:0;padding:10px 14px;border-radius:7px;text-decoration:none;display:inline-block}.msg{padding:10px;background:#e4f5ec}.err{background:#ffe9e6}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><main class="wrap"><h1>Proveedores y compras</h1><p><?=htmlspecialchars($msg?:$err)?></p><section class="box"><h2>Agregar proveedor</h2><form method="post" class="grid"><input type="hidden" name="accion" value="proveedor"><div><label>Nombre</label><input name="nombre" required></div><div><label>Documento</label><input name="documento"></div><div><label>Teléfono</label><input name="telefono"></div><div><label>&nbsp;</label><button>Guardar proveedor</button></div></form></section><section class="box"><h2>Registrar compra y lote</h2><form method="post" class="grid"><input type="hidden" name="accion" value="compra"><div><label>Proveedor</label><select name="proveedor_id" required><option value="">Selecciona</option><?php foreach($provs as $p){ ?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nombre'])?></option><?php } ?></select></div><div><label>Medicamento</label><select name="producto_id" required><option value="">Selecciona</option><?php foreach($prods as $p){ ?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nombre'])?></option><?php } ?></select></div><div><label>Número de compra</label><input name="numero" required></div><div><label>Lote del fabricante</label><input name="lote" required></div><div><label>Vencimiento</label><input type="date" name="vencimiento" required></div><div><label>Cantidad</label><input type="number" name="cantidad" min="1" required></div><div><label>Costo unitario (RD$)</label><input type="number" name="costo" min="0" step="0.01" required></div><div><label>&nbsp;</label><button>Registrar compra</button></div></form></section><a class="btn" href="index.php">Volver al sistema</a></main></body></html>
